/**
 * D-444 -- flashcards for OxfordAQA International GCSE Islamiyat 9237
 * (specification Version 1.1).
 *
 * One block per subtopic, in specification order. Card ids are
 * `<subtopic number>-<n>` and are permanent (browser progress is keyed by
 * them): add a new card with the next unused n, never renumber.
 *
 *   src: '...'  The card restates that revision-notes page (found with
 *               scripts/flashcard-candidates.mjs 9237); origin 'revision-notes'.
 *
 * Written from Marlbridge's own 9237 revision notes and study guides (Living
 * the Muslim life, Sources of authority), using their transliterations. The
 * 3.1.1.1 to 3.2.2.10 blocks (one per specification subtopic, ids such as
 * `3.1.1.1-1`) were written on 20 Nov 2026 from the revision-notes page for
 * each subtopic; the earlier 3.1.1, 3.1.2, 3.2.1 and 3.2.2 blocks keep to
 * the standard dates and events. Cards state what Muslims
 * believe and practise, factually; they give no rulings or opinions.
 *
 * Not tiered. Plain text only (see types.ts).
 */
import type { Flashcard, FlashcardDeck } from './types.ts';

interface Spec { n: number; f: string; b: string; src?: string }

const sub = (topic: string, subtopic: string, number: string, specs: Spec[]): Flashcard[] =>
  specs.map(({ n, f, b, src }) => ({
    id: `${number}-${n}`,
    topic,
    subtopic,
    front: f,
    back: b,
    origin: src ? 'revision-notes' as const : 'authored' as const,
    ...(src ? { source: src } : {}),
  }));

const SOA = 'igcse-oxfordaqa-islamiyat-sources-of-authority-revision-notes';
/** Revision-notes page for one of the 9237 subtopic scopes (3.1.1.1 to 3.2.2.10). */
const RN = (slug: string) => `oxfordaqa-igcse-islamiyat-9237-${slug}-revision-notes`;

const P1 = 'paper-1-living-muslim-life-9237';
const P2 = 'paper-2-life-hazrat-muhammad-9237';

export const DECK_OXFORDAQA_IGCSE_ISLAMIYAT: FlashcardDeck = {
  boardSlug: 'oxfordaqa',
  qualificationSlug: 'igcse',
  subjectSlug: 'islamiyat',
  // D-484: recorded on the owner's word (16 Nov 2026), accountable teacher for this course.
  deckReview: { reviewerSlug: 'azam-siddique', reviewedOn: '2026-11-16' },
  syllabusCode: '9237',
  syllabusSeries: 'Version 1.1',
  author: 'marlbridge-academic-team',
  updated: '2026-11-20',
  cards: [
    // Paper 1 Living the Muslim life
    ...sub(P1, 'islam-beliefs-teachings-9237', '3.1.1', [
      { n: 1, f: 'What are the six Articles of Faith?', b: 'Tawhid (the oneness of God), belief in the angels, the revealed books, the prophets, the Day of Judgement, and al-qadr (divine decree).' },
      { n: 2, f: 'Why is tawhid described as the foundation of Muslim belief?', b: 'Every other belief and practice follows from it: worship is directed to God alone, with no intermediaries, and all believers are equal before Him.' },
      { n: 3, f: 'What is shirk?', b: 'Associating partners with God, the opposite of tawhid. Muslims regard it as the gravest sin.' },
      { n: 4, f: 'What is al-qadr?', b: 'Divine decree: the belief that God knows and has power over everything that happens, while humans remain responsible for their choices.' },
      { n: 5, f: 'What role does the angel Jibril have?', b: 'He brought God’s revelation to the prophets, including the Qur’an to Hazrat Muhammad (pbuh).' },
      { n: 6, f: 'Which books do Muslims believe God revealed, and to whom?', b: 'The Tawrat to Musa, the Zabur to Dawud, the Injil to Isa and the Qur’an to Muhammad (pbuh), as well as the Scrolls of Ibrahim.' },
      { n: 7, f: 'What do Muslims believe about the Day of Judgement?', b: 'All people will be resurrected and judged by God on their beliefs and deeds, and rewarded with paradise or punished in hell.' },
      { n: 8, f: 'What does it mean that Muhammad (pbuh) is the “Seal of the Prophets”?', b: 'That he is the last prophet, completing the message brought by the earlier prophets.' },
    ]),
    ...sub(P1, 'islam-practices-9237', '3.1.2', [
      { n: 1, f: 'What are the Five Pillars of Islam?', b: 'Shahadah (declaration of faith), Salah (five daily prayers), Zakat (annual almsgiving), Sawm (fasting in Ramadan) and Hajj (pilgrimage to Makkah, once in a lifetime if able).' },
      { n: 2, f: 'Why is the Shahadah considered the foundation of the Five Pillars?', b: 'Accepting and declaring it is what makes a person a Muslim; the other four pillars are practices that follow from that belief.' },
      { n: 3, f: 'Name the five daily prayers', b: 'Fajr (dawn), Zuhr (midday), Asr (afternoon), Maghrib (sunset) and Isha (night).' },
      { n: 4, f: 'What are wudu, the Qiblah and a rak’ah?', b: 'Wudu: ritual washing before prayer. Qiblah: the direction of the Ka’bah in Makkah, which Muslims face to pray. Rak’ah: one sequence of the movements and recitations of prayer.' },
      { n: 5, f: 'Why is Jumu’ah (Friday prayer) significant?', b: 'It is a congregational prayer at the mosque that includes a khutbah (sermon), so it unites the community and provides teaching in a way individual prayer does not.' },
      { n: 6, f: 'What is the difference between Zakat and sadaqah?', b: 'Zakat is an obligatory annual payment, traditionally 2.5% of qualifying wealth above the nisab threshold. Sadaqah is voluntary charity given at any time, in any amount.' },
      { n: 7, f: 'What is the nisab?', b: 'The minimum level of qualifying wealth above which Zakat is due. Below it, no payment is due.' },
      { n: 8, f: 'What is the significance of Sawm in Ramadan?', b: 'Self-discipline, empathy with the poor, spiritual focus, and remembering the first revelation of the Qur’an, which came in Ramadan on Laylat al-Qadr (the Night of Power).' },
      { n: 9, f: 'What is the significance of the ihram garments on Hajj?', b: 'All pilgrims wear the same simple white garments, so wealth and status are invisible and all stand equal before God.' },
      { n: 10, f: 'Why is standing at Arafat the essential rite of Hajj?', b: 'Pilgrims spend the afternoon of the 9th of Dhul-Hijjah there in prayer and supplication. It is also where the Prophet delivered his Farewell Sermon.' },
      { n: 11, f: 'What is the difference between Eid-ul-Fitr and Eid-ul-Adha?', b: 'Eid-ul-Fitr marks the end of Ramadan; Zakat-ul-Fitr is given before the prayer. Eid-ul-Adha falls during Hajj and commemorates Ibrahim’s willingness to sacrifice his son; the qurbani meat is shared in three parts.' },
      { n: 12, f: 'What is the difference between du’a and Salah?', b: 'Du’a is personal supplication, in any words and at any time. Salah is the prescribed prayer with a fixed form and fixed times.' },
      { n: 13, f: 'What do halal and haram mean?', b: 'Halal: permitted. Haram: forbidden. They shape daily conduct, including food, honesty in trade, the prohibition of interest, and duties to parents, neighbours and the needy.' },
    ]),
    ...sub(P1, 'the-oneness-of-god-tawhid-9237', '3.1.1.1', [
      { n: 1, f: 'What are the three types of Tawhid?', b: 'Rububiyyah (Allah alone creates, owns and sustains), Uluhiyyah (Allah alone is worshipped and asked for help) and Asma wa as-Sifat (Allah’s names and qualities are unique).', src: RN('oneness-of-god-tawhid') },
      { n: 2, f: 'Which verse says “There is nothing like unto Him”, and which type of Tawhid does it support?', b: 'Qur’an 42:11. It supports Tawhid al-Asma wa as-Sifat: Allah’s names and qualities are unique and cannot be compared with anything created.', src: RN('oneness-of-god-tawhid') },
      { n: 3, f: 'What does As-Samad mean in Surah al-Ikhlas (112)?', b: 'The Eternal Refuge: all creation depends on Allah, and He depends on no one.', src: RN('oneness-of-god-tawhid') },
      { n: 4, f: 'What does “He neither begets nor is born” (112:3) teach?', b: 'Allah has no children and no parents and no beginning, so nothing is part of Him and nothing can be His equal.', src: RN('oneness-of-god-tawhid') },
      { n: 5, f: 'What is the difference between major shirk and minor shirk?', b: 'Major shirk is worshipping others or giving them Allah’s powers, such as idol worship, and puts a person outside Islam unless repented. Minor shirk is show-off (riya’), a grave sin that reduces reward.', src: RN('oneness-of-god-tawhid') },
      { n: 6, f: 'Why did the Prophet (pbuh) stress Tawhid al-Uluhiyyah in Makkah?', b: 'The people of Makkah accepted that Allah is the Creator (Rububiyyah) but still worshipped idols as intermediaries, so they did not give worship to Allah alone.', src: RN('oneness-of-god-tawhid') },
      { n: 7, f: 'Give three reasons why Tawhid is important for a Muslim', b: 'It is the basis of the Shahadah; it gives equality, as all are servants of one Lord; and it frees a person from fear, because only Allah brings benefit or harm.', src: RN('oneness-of-god-tawhid') },
      { n: 8, f: 'Exam trap: do Muslims worship the Ka’bah or Muhammad (pbuh)?', b: 'No. Muslims worship Allah alone. The Ka’bah is the Qiblah that unites them in prayer, and Muhammad (pbuh) is the final prophet and a model, not an object of worship.', src: RN('oneness-of-god-tawhid') },
    ]),
    ...sub(P1, 'key-beliefs-9237', '3.1.1.2', [
      { n: 1, f: 'List the six key beliefs by their Arabic names', b: 'Tawhid (oneness of Allah), Malaikah (angels), Kutub (books), Risalah (messengers), Yaum e Akhirah (the Last Day) and Al-Qadr (the decree).', src: RN('key-beliefs') },
      { n: 2, f: 'Which verse lists belief in the Last Day alongside Allah, angels, books and messengers?', b: 'Qur’an 4:136. Verse 2:285 lists Allah, His angels, His books and His messengers.', src: RN('key-beliefs') },
      { n: 3, f: 'Which source gives all six key beliefs, including the decree “its good and its bad”?', b: 'The Hadith of Jibril in Sahih Muslim. The version in Sahih al-Bukhari 50 has a shorter list of beliefs.', src: RN('key-beliefs') },
      { n: 4, f: 'Does “all good and bad is from Allah” mean that Allah makes people do evil?', b: 'No. Everything happens within Allah’s knowledge and permission, but humans choose their actions and are responsible for them. Hardship is a test.', src: RN('key-beliefs') },
      { n: 5, f: 'What does “We make no distinction between any of His messengers” (2:285) mean?', b: 'Muslims honour every prophet and do not accept one while rejecting another. This is the key teaching on Risalah in the passage.', src: RN('key-beliefs') },
      { n: 6, f: 'What does “We hear and we obey” (2:285) show about belief?', b: 'Belief is meant to lead to action. Faith in the heart is shown by obeying Allah in daily life.', src: RN('key-beliefs') },
      { n: 7, f: 'What are the Shi’a “roots of religion” (usul ad-din)?', b: 'Twelver Shi’a Muslims hold five: Tawhid, ‘Adl (justice), Nubuwwah (prophethood), Imamah (leadership) and Ma’ad (the Return). Sunni Muslims hold the six key beliefs.', src: RN('key-beliefs') },
      { n: 8, f: 'How do the key beliefs differ from the Five Pillars?', b: 'The key beliefs are what Muslims accept (iman, faith). The Five Pillars are what they do (practice). Each belief should lead to behaviour.', src: RN('key-beliefs') },
    ]),
    ...sub(P1, 'concept-of-belief-in-allah-9237', '3.1.1.3', [
      { n: 1, f: 'How many names of Allah are to be learned, and does this limit Allah to 99 names?', b: 'Ninety-nine. A Hadith in Bukhari and Muslim promises Paradise to whoever memorises them, but it does not limit Allah to 99 names. Qur’an 7:180 says to invoke Him by His best names.', src: RN('concept-of-belief-in-allah') },
      { n: 2, f: 'What is the difference between Qudrah and Al-Qadir?', b: 'Qudrah is the attribute: power, omnipotence. Al-Qadir is the name of Allah that expresses it: the All-Powerful, for whom nothing is beyond His ability.', src: RN('concept-of-belief-in-allah') },
      { n: 3, f: 'How do Ar-Rehman and Ar-Raheem differ?', b: 'Ar-Rehman is wide mercy to all creation in this world. Ar-Raheem is special, lasting mercy, especially for believers and in the Hereafter.', src: RN('concept-of-belief-in-allah') },
      { n: 4, f: 'What does Al-Khaliq mean, and which names appear with it in 59:24?', b: 'Al-Khaliq means the Creator, who brings everything into being. In 59:24 it appears with Al-Bari’ (the Originator) and Al-Musawwir (the Fashioner, who gives form).', src: RN('concept-of-belief-in-allah') },
      { n: 5, f: 'What does Al-Aleem teach a Muslim?', b: 'Allah knows the seen and the unseen, the open and the secret (6:59). This encourages honesty, even in private, and gives comfort that Allah knows every hardship.', src: RN('concept-of-belief-in-allah') },
      { n: 6, f: 'What does the Hadith of the hundred parts of mercy teach?', b: 'Allah created a hundred parts of mercy and sent one to earth, which is why creatures show kindness. He keeps ninety-nine parts for the Last Day.', src: RN('concept-of-belief-in-allah') },
      { n: 7, f: 'Give two ways in which Muslims use the names of Allah in daily life', b: 'In prayer (du’a), in the Bismillah ir-Rahman ir-Raheem, and in personal names that join Abd (servant of) to a name of Allah, such as Abdur-Rahman.', src: RN('concept-of-belief-in-allah') },
      { n: 8, f: 'How does belief in Qudrah affect a Muslim facing difficulty?', b: 'It gives hope and humility: nothing is beyond Allah’s power, so a Muslim does not give up but makes an effort and asks Allah for help. Qur’an 2:20: He is over all things competent.', src: RN('concept-of-belief-in-allah') },
    ]),
    ...sub(P1, 'belief-in-angels-9237', '3.1.1.4', [
      { n: 1, f: 'What are angels (malaikah) and what are their main qualities?', b: 'Beings created from light who obey Allah without fail. They are unseen, never tire of worship, have wings, can take human form, and are not divine or worshipped.', src: RN('belief-in-angels') },
      { n: 2, f: 'What are the roles of Jibril and Mika’il?', b: 'Jibril brings revelation to the prophets, above all the Qur’an (2:97). Mika’il is linked by tradition to rain and provision (2:98).', src: RN('belief-in-angels') },
      { n: 3, f: 'What are the roles of Isra’fil and Malak-al-Mowth?', b: 'Isra’fil will blow the trumpet on the Last Day (39:68). Malak-al-Mowth, the angel of death, takes souls at the appointed time (32:11).', src: RN('belief-in-angels') },
      { n: 4, f: 'Who are the Kiraman Katibeen and why do they matter?', b: 'The noble recorders, one on each shoulder, who write down every deed (82:10-12). They teach accountability: a Muslim tries to behave well even when alone.', src: RN('belief-in-angels') },
      { n: 5, f: 'What are the four questions in the Hadith of Jibril?', b: 'The stranger asked about Iman (faith), Islam, Ihsan (excellence) and the Hour. The Prophet (pbuh) then said it was Jibril, who came to teach the people their religion.', src: RN('belief-in-angels') },
      { n: 6, f: 'What are the three levels of religion in the Hadith of Jibril?', b: 'Islam (practice, what the body does), Iman (belief, what the heart believes) and Ihsan (excellence: worship as if you see Allah, knowing that He sees you).', src: RN('belief-in-angels') },
      { n: 7, f: 'Exam trap: was Iblis an angel, and do angels have free will?', b: 'No to both. Iblis was a jinn (18:50). Angels have no free will and never disobey Allah (66:6); humans and jinn can choose.', src: RN('belief-in-angels') },
      { n: 8, f: 'What does Qur’an 35:1 teach about angels?', b: 'Allah made the angels messengers with wings “two or three or four”. They are creatures of the Creator, carrying out His commands, and He is over all things competent.', src: RN('belief-in-angels') },
    ]),
    ...sub(P1, 'belief-in-predestination-al-qadr-9237', '3.1.1.5', [
      { n: 1, f: 'Define Al-Qadr (predestination)', b: 'The belief that Allah knows all things before they happen, has written them, wills them and creates them. Nothing happens outside His knowledge, yet humans still choose and are responsible.', src: RN('belief-in-predestination-al-qadr') },
      { n: 2, f: 'What are the four levels of Al-Qadr?', b: 'Ilm (Allah knows everything), Kitabah (it is written in the Preserved Tablet), Mashee’ah (nothing happens unless Allah wills) and Khalq (Allah creates all things and means).', src: RN('belief-in-predestination-al-qadr') },
      { n: 3, f: 'Why does belief in Al-Qadr not remove human responsibility?', b: 'Knowing is not forcing. The Qur’an tells people to choose (18:29), Allah does not burden a soul beyond its ability (2:286), and people are judged on their choices.', src: RN('belief-in-predestination-al-qadr') },
      { n: 4, f: 'In Sahih al-Bukhari 1362, how did the Prophet (pbuh) answer the man who asked whether people should rely on what is written?', b: 'He said good deeds are made easy for the blessed and bad deeds for the wretched, then recited 92:5-6. The message: do not use the decree as an excuse; act.', src: RN('belief-in-predestination-al-qadr') },
      { n: 5, f: 'What did Umar (RA) say about turning back from a land struck by plague?', b: '“We flee from the decree of Allah to the decree of Allah.” Taking precautions is part of belief in Al-Qadr.', src: RN('belief-in-predestination-al-qadr') },
      { n: 6, f: 'How does belief in Al-Qadr influence a Muslim in hardship and in success?', b: 'In hardship: patience (sabr), saying “Inna lillahi wa inna ilayhi raji’un” (2:156). In success: gratitude (shukr) and no pride. Failure is not a reason to despair.', src: RN('belief-in-predestination-al-qadr') },
      { n: 7, f: 'How does Al-Qadr differ from fatalism?', b: 'Fatalism says everything is fixed so effort is pointless. Al-Qadr holds that Allah’s knowledge is complete, choice is real, effort is commanded and rewarded, and wrongdoing must be repented of.', src: RN('belief-in-predestination-al-qadr') },
      { n: 8, f: 'What does tawakkul mean, and what is the Hadith linked to it?', b: 'Trust in Allah after making effort. The Prophet (pbuh) said “Tie it and trust in Allah” (Tirmidhi): tie the camel, then rely on Allah.', src: RN('belief-in-predestination-al-qadr') },
    ]),
    ...sub(P1, 'belief-in-life-after-death-9237', '3.1.1.6', [
      { n: 1, f: 'Put the stages of the journey after death in order', b: 'Death, Barzakh, the trumpet and resurrection, judgement, then Jannah (Paradise) or Jahannam (Hell).', src: RN('belief-in-life-after-death') },
      { n: 2, f: 'What is Barzakh?', b: 'The barrier between death and resurrection (23:100). Two angels question the dead person. It is a waiting stage, not the final outcome and not Paradise or Hell.', src: RN('belief-in-life-after-death') },
      { n: 3, f: 'What happens at the Judgement according to the notes?', b: 'Each person receives a record of deeds, in the right hand (success) or left (failure), deeds are weighed on scales, and hands, feet and the earth testify. Allah’s mercy is greater than His anger.', src: RN('belief-in-life-after-death') },
      { n: 4, f: 'What is the greatest reward of Jannah?', b: 'The pleasure of Allah and seeing Him (75:22-23), beyond the gardens, rivers, peace and reunion with the righteous that are described in human language.', src: RN('belief-in-life-after-death') },
      { n: 5, f: 'What is the message of Qur’an 80:34-37?', b: 'On that Day a person will flee from siblings, parents, spouse and children, because each is occupied with their own account. It teaches individual responsibility.', src: RN('belief-in-life-after-death') },
      { n: 6, f: 'Give the death rituals in order', b: 'Shahadah near death, closing the eyes, ghusl (washing), kafan (plain white shroud), Salat al-Janazah (funeral prayer), then prompt burial facing the Qiblah, followed by mourning and support for the family.', src: RN('belief-in-life-after-death') },
      { n: 7, f: 'What is fard kifayah, and how does it apply to the funeral prayer?', b: 'A duty on the community as a whole: if enough people perform it, everyone is relieved. The funeral prayer is fard kifayah.', src: RN('belief-in-life-after-death') },
      { n: 8, f: 'How do Sunni and Shi’a Muslims differ in the Janazah prayer, and how long does a widow mourn?', b: 'Sunni Muslims say four takbirs and Shi’a Muslims five. A widow observes four months and ten days (2:234); other mourning lasts three days.', src: RN('belief-in-life-after-death') },
    ]),
    ...sub(P1, 'prophethood-nabuat-and-holy-books-in-islam-9237', '3.1.1.7', [
      { n: 1, f: 'What is the difference between a nabi and a rasul?', b: 'A nabi is a prophet: a human chosen to receive revelation. A rasul is a messenger: a prophet who brings a message or a book.', src: RN('prophethood-and-holy-books') },
      { n: 2, f: 'Match each book to its prophet: Suhuf, Tawrat, Zabur, Injil, Qur’an', b: 'Suhuf to Ibraheem, Tawrat to Musa, Zabur to Dawud, Injil to Isa, and the Qur’an to Muhammad (pbuh), the final and preserved book (15:9).', src: RN('prophethood-and-holy-books') },
      { n: 3, f: 'What lessons come from the story of Adam (AS)?', b: 'He was the first human and prophet, and khalifah (steward) of the earth. He repented (7:23) and Allah forgave him, so repentance is open to all and there is no inherited sin.', src: RN('prophethood-and-holy-books') },
      { n: 4, f: 'What are the key events in the life of Ibraheem (AS)?', b: 'He rejected idols, was thrown into fire that Allah made cool and safe (21:69), left Hajar and Isma’il in Makkah, was ready to sacrifice his son, and built the Ka’bah with Isma’il.', src: RN('prophethood-and-holy-books') },
      { n: 5, f: 'Why is Musa (AS) called Kalimullah?', b: 'Because Allah spoke to him directly (4:164), at the burning bush. He later confronted Pharaoh, led the Exodus and received the Tawrat.', src: RN('prophethood-and-holy-books') },
      { n: 6, f: 'What do Muslims believe about Isa (AS)?', b: 'He was a mighty prophet born miraculously to Maryam, who received the Injil, but he was not divine or God’s son. He was not crucified; Allah raised him (4:157-158).', src: RN('prophethood-and-holy-books') },
      { n: 7, f: 'What does the Seal of Prophethood mean, and which verse states it?', b: 'Qur’an 33:40 calls Muhammad (pbuh) the last of the prophets. So the Qur’an is final, the message is universal and the Sunnah is the model.', src: RN('prophethood-and-holy-books') },
      { n: 8, f: 'What is tahrif, and what do Muslims believe about the earlier books?', b: 'Tahrif is alteration of a text. Muslims believe the earlier books came from Allah, but that parts were changed or lost; the Qur’an confirms and is a criterion over them (5:48).', src: RN('prophethood-and-holy-books') },
    ]),
    ...sub(P1, 'the-early-leadership-of-the-muslim-community-9237', '3.1.1.8', [
      { n: 1, f: 'Give the four rightly guided Caliphs in order, with their dates', b: 'Abu Bakr (632-634), Umar (634-644), Uthman (644-656) and Ali (656-661), together about 29 years. They are the Khulafa ar-Rashidun.', src: RN('early-leadership-muslim-community') },
      { n: 2, f: 'How was each of the four Caliphs chosen?', b: 'Abu Bakr by consultation and public pledge; Umar nominated by Abu Bakr; Uthman by a committee of six; Ali by pledge of the people of Madinah.', src: RN('early-leadership-muslim-community') },
      { n: 3, f: 'What were the main achievements of Abu Bakr (RA)?', b: 'He held the community together after the Prophet’s death, fought the Ridda wars, and had the Qur’an collected after Yamama, with Zayd ibn Thabit. His title was As-Siddiq.', src: RN('early-leadership-muslim-community') },
      { n: 4, f: 'What were the main achievements of Umar (RA)?', b: 'Conquests in Syria, Egypt, Iraq and Persia, a treaty for Jerusalem, provinces, judges and the diwan, and the Hijri calendar. His title was Al-Faruq. He was killed in prayer in 644.', src: RN('early-leadership-muslim-community') },
      { n: 5, f: 'What were the main achievements of Uthman (RA)?', b: 'He sent standard copies of the Qur’an to the cities, built a navy and enlarged the Prophet’s Mosque. He was called Dhun-Nurayn and was killed after a siege in 656.', src: RN('early-leadership-muslim-community') },
      { n: 6, f: 'Who was Ali (RA), and what marked his time as Caliph?', b: 'The Prophet’s cousin and son-in-law, known for knowledge and justice. His rule saw the Battles of the Camel and Siffin; he moved the capital to Kufa and was killed in 661.', src: RN('early-leadership-muslim-community') },
      { n: 7, f: 'How do Sunni and Shi’a Muslims differ on leadership after the Prophet (pbuh)?', b: 'Sunni Muslims believe the community chose Abu Bakr by consultation. Shi’a Muslims believe the Prophet named Ali at Ghadir Khumm, so Ali is the first Imam. Both honour Ali.', src: RN('early-leadership-muslim-community') },
      { n: 8, f: 'What does Hadith 28 of an-Nawawi teach?', b: 'Have taqwa, listen and obey the leader, keep to the Prophet’s Sunnah and that of the Khulafa ar-Rashideen, and beware of newly invented matters (bid’ah) in religion.', src: RN('early-leadership-muslim-community') },
    ]),
    ...sub(P1, 'the-key-practices-in-islam-9237', '3.1.2.1', [
      { n: 1, f: 'Name the Five Pillars of Islam and the main purpose of each', b: 'Shahadah (entry into Islam), Salah (remembrance and discipline), Sawm (self-control and taqwa), Zakah (purifies wealth and helps the poor) and Hajj (unity, equality and submission).', src: RN('key-practices-in-islam') },
      { n: 2, f: 'Why is Hajj not required of everyone?', b: 'It is only for those who are able in health and means (“for whoever is able”, 3:97). Zakah is likewise due only once wealth reaches the nisab.', src: RN('key-practices-in-islam') },
      { n: 3, f: 'What do Amr bil maroof and Nahi annil munkar mean?', b: 'Amr bil maroof is commanding or encouraging what is good. Nahi annil munkar is forbidding or discouraging what is wrong. Sources include Qur’an 3:104 and 3:110.', src: RN('key-practices-in-islam') },
      { n: 4, f: 'What are the three levels of changing a wrong in the Hadith in Sahih Muslim?', b: 'By hand (only with right and ability, respecting the law), by tongue (advising wisely and kindly) and by heart (disliking the wrong), which is the weakest level of faith.', src: RN('key-practices-in-islam') },
      { n: 5, f: 'What conditions should apply when forbidding wrong?', b: 'Knowledge, gentleness, starting with oneself (2:44), avoiding causing greater harm, and using lawful means. It does not mean taking the law into your own hands.', src: RN('key-practices-in-islam') },
      { n: 6, f: 'What does the Hadith of the ship teach?', b: 'If people on the lower deck pierce the hull and the others do not stop them, all drown. The whole community is responsible for preventing wrong.', src: RN('key-practices-in-islam') },
      { n: 7, f: 'What does the Hadith of Jibril (Bukhari 50) say Ihsan is?', b: 'To worship Allah as if you see Him; if you cannot, He sees you. It is the sincerity behind the pillars. The Hadith defines Islam through actions.', src: RN('key-practices-in-islam') },
      { n: 8, f: 'What are the practices that Twelver Shi’a Muslims call Furu’ ad-Din?', b: 'Ten practices, including prayer, fasting, Hajj, Zakah, Khums, Jihad, enjoining good, forbidding evil, Tawalla (love for the Prophet’s family) and Tabarra (disassociation from their enemies).', src: RN('key-practices-in-islam') },
    ]),
    ...sub(P1, 'shahadah-9237', '3.1.2.2', [
      { n: 1, f: 'What is the Shahadah, and what do its two halves teach?', b: '“I bear witness that there is no god but Allah, and Muhammad is the Messenger of Allah.” The first half teaches Tawhid (oneness) and the second Risalah (messengership).', src: RN('shahadah') },
      { n: 2, f: 'What do la ilaha and illa Allah mean?', b: 'La ilaha rejects false gods (“there is no god”) and illa Allah affirms Allah alone (“but Allah”): negation, then affirmation.', src: RN('shahadah') },
      { n: 3, f: 'List the seven conditions of the Shahadah given by scholars', b: 'Knowledge, certainty, acceptance, submission, truthfulness, sincerity and love.', src: RN('shahadah') },
      { n: 4, f: 'Give three moments in a Muslim’s life when the Shahadah is used', b: 'On becoming a Muslim, in the Azaan and Iqamah, in the Tashahhud of every prayer, whispered to a newborn, at the start of the Friday khutbah, and as the last words before death.', src: RN('shahadah') },
      { n: 5, f: 'Why does the Shahadah need both halves?', b: 'Tawhid shows whom to worship; Risalah shows how, through the example of the messenger. Together they sum up the faith and are the foundation of the other four pillars.', src: RN('shahadah') },
      { n: 6, f: 'What does Qur’an 3:18 say about who bears witness to Tawhid?', b: 'Allah Himself witnesses that there is no deity except Him, and so do the angels and those of knowledge, maintaining creation in justice.', src: RN('shahadah') },
      { n: 7, f: 'What does a person need to do to become a Muslim?', b: 'Say the Shahadah sincerely, ideally with witnesses. No priest or special ceremony is required.', src: RN('shahadah') },
      { n: 8, f: 'What is the difference in the Shahadah between Sunni and Shi’a practice?', b: 'Shi’a Muslims often add a statement about Ali (RA) as wali (friend) of Allah in the Azaan or prayer; many Shi’a scholars say it is not part of the Shahadah. Both agree on the two core statements.', src: RN('shahadah') },
    ]),
    ...sub(P1, 'salah-9237', '3.1.2.3', [
      { n: 1, f: 'How many fard rak’ahs are in each of the five daily prayers, and what is the total?', b: 'Fajr 2, Zuhr 4, Asr 4, Maghrib 3, Isha 4: seventeen in a day. Sunnah and nafl prayers are extra.', src: RN('salah') },
      { n: 2, f: 'Why do Muslims pray? Give four reasons', b: 'Obedience to Allah, remembrance of Him (20:14), protection from wrongdoing (29:45) and following the Prophet (pbuh): “Pray as you have seen me praying.” Also forgiveness, gratitude and accountability.', src: RN('salah') },
      { n: 3, f: 'What are the conditions for valid Salah?', b: 'A pure body, clothes and place, being covered, facing the Qiblah, praying at the correct time, and intention. Wudu is needed first; tayammum replaces it if there is no water or it would cause harm.', src: RN('salah') },
      { n: 4, f: 'Outline one rak’ah', b: 'Takbir, standing with al-Fatiha, bowing, standing, then two prostrations with a sitting between. The prayer ends with the Tashahhud, blessings on the Prophet (pbuh) and salam to right and left.', src: RN('salah') },
      { n: 5, f: 'What concessions does Salah allow, and what is the principle?', b: 'Travellers shorten (qasr) and may combine prayers; the ill pray sitting or lying; tayammum replaces wudu; menstruating women are excused. “Allah intends for you ease” (2:185). Concessions change how, not whether.', src: RN('salah') },
      { n: 6, f: 'Compare praying at home and in the mosque', b: 'Home gives privacy, lets children learn and suits extra prayers. The mosque gives unity, equality in rows, an imam and community; congregation is 27 times better (Bukhari and Muslim).', src: RN('salah') },
      { n: 7, f: 'What are the key facts about Jummah (Friday prayer)?', b: 'At Friday midday it replaces Zuhr, with a khutbah in two parts and two fard rak’ahs. It is obligatory for adult resident men; women and travellers are not required (62:9).', src: RN('salah') },
      { n: 8, f: 'What does Qur’an 62:9-11 teach about prayer and work?', b: 'Verse 9 puts prayer before trade; verse 10 permits work afterwards while remembering Allah; verse 11 warns against being distracted by trade or amusement.', src: RN('salah') },
      { n: 9, f: 'Exam trap: how does Salah differ from du’a, and do Muslims worship the Ka’bah?', b: 'Salah is the formal prescribed prayer at set times; du’a is personal supplication at any time. Muslims face the Ka’bah as the Qiblah but worship Allah alone.', src: RN('salah') },
    ]),
    ...sub(P1, 'sawm-9237', '3.1.2.4', [
      { n: 1, f: 'What is Sawm, and what is its aim?', b: 'Abstaining from food, drink and sexual relations from true dawn to sunset, with intention, in Ramadhan. Its aim is “that you may become righteous” (2:183): taqwa.', src: RN('sawm') },
      { n: 2, f: 'Who is exempt from fasting, and what must they do?', b: 'Those temporarily ill, travelling, or menstruating make up the days (qada). The permanently ill or very old feed a poor person for each day (fidya). Children are not obliged before puberty.', src: RN('sawm') },
      { n: 3, f: 'What is the difference between qada and fidya?', b: 'Qada is making up missed fasts later. Fidya is feeding a poor person in place of fasting, for those who cannot fast at all. Fidya is not the same as qada.', src: RN('sawm') },
      { n: 4, f: 'Which actions break the fast and which do not?', b: 'Eating or drinking on purpose, sexual relations and deliberate vomiting break it. Eating by mistake, bathing, and brushing teeth without swallowing do not. Lying and backbiting do not break it technically but ruin the reward.', src: RN('sawm') },
      { n: 5, f: 'Give a spiritual, a moral and a social benefit of Sawm', b: 'Spiritual: taqwa and closeness to Allah. Moral: self-control and patience. Social: empathy with the poor, generosity (Zakat-ul-Fitr) and the unity of the Ummah.', src: RN('sawm') },
      { n: 6, f: 'What are Taraweeh and Itikaaf?', b: 'Taraweeh is a voluntary night prayer after Isha in Ramadhan, often completing the Qur’an. Itikaaf is a retreat in the mosque, normally the last ten days, seeking Laylat ul-Qadr.', src: RN('sawm') },
      { n: 7, f: 'What is Laylat ul-Qadr?', b: 'The Night of Power, when the Qur’an was first revealed (Surah 97). It is better than a thousand months, about 83 years, and is sought on the odd nights of the last ten of Ramadhan.', src: RN('sawm') },
      { n: 8, f: 'Why does Ramadhan move through the seasons?', b: 'Twelve lunar months are about 354 days against about 365 in a solar year, so Ramadhan starts about 11 days earlier each year and returns to the same season after about 33 years.', src: RN('sawm') },
    ]),
    ...sub(P1, 'zakah-9237', '3.1.2.5', [
      { n: 1, f: 'What does Zakah mean, and how does it differ from sadaqah?', b: 'Zakah means purification and growth: compulsory yearly giving from qualifying wealth, the third Pillar. Sadaqah is voluntary charity at any time, in any amount.', src: RN('zakah') },
      { n: 2, f: 'What conditions must a person meet before Zakah is due?', b: 'A Muslim adult of sound mind, holding wealth at or above the nisaab for one full lunar year (hawl), surplus to basic needs after debts due.', src: RN('zakah') },
      { n: 3, f: 'What is the rate of Zakah on savings, and how is it calculated?', b: '2.5 per cent (one-fortieth). Add qualifying wealth, subtract debts due, compare with the nisaab, then multiply by 0.025. For example, 9,500 minus 500 debt = 9,000; 9,000 × 0.025 = 225.', src: RN('zakah') },
      { n: 4, f: 'What is Ushr, and what are its two rates?', b: 'Zakah on farm produce, paid at harvest. It is 10 per cent for rain-fed or naturally watered crops and 5 per cent where irrigation is costly, since more effort means less is due.', src: RN('zakah') },
      { n: 5, f: 'Name the eight groups who may receive Zakah (9:60)', b: 'The poor, the needy, collectors of Zakah, those whose hearts are to be reconciled, freeing captives or slaves, those in debt, the cause of Allah, and the stranded traveller.', src: RN('zakah') },
      { n: 6, f: 'Who is not normally eligible to receive Zakah?', b: 'Someone rich enough to pay Zakah, the giver’s own dependent parents, spouse or children, and (according to most scholars) members of the Prophet’s family.', src: RN('zakah') },
      { n: 7, f: 'Why do Muslims give Zakah? Give three reasons', b: 'It is a duty from Allah (9:60); wealth is a trust (amanah) held for Him; it purifies the giver (9:103); and wealth must not circulate only among the rich (59:7).', src: RN('zakah') },
      { n: 8, f: 'What did Abu Bakr (RA) do about tribes that stopped paying Zakah after the Prophet’s death?', b: 'He insisted they must pay. This shows that Zakah is a binding obligation of the community, not an optional gift.', src: RN('zakah') },
    ]),
    ...sub(P1, 'hajj-9237', '3.1.2.6', [
      { n: 1, f: 'Who must perform Hajj, and when?', b: 'Every adult Muslim of sound mind who is physically and financially able, once in a lifetime (3:97), in Dhul Hijjah. The journey must be safe and the family’s needs met.', src: RN('hajj') },
      { n: 2, f: 'What are Ihram and Meeqat?', b: 'Meeqat: the fixed boundary points around Makkah. Ihram: the state of purity entered there, with intention and the Talbiyah. Men wear two white unsewn sheets.', src: RN('hajj') },
      { n: 3, f: 'What is forbidden while in Ihram?', b: 'Cutting hair or nails, perfume, hunting, sexual relations, arguing and wrongdoing. This shows equality, humility and full focus on Allah.', src: RN('hajj') },
      { n: 4, f: 'Put the rites of Hajj in order, from the 8th of Dhul Hijjah', b: 'Mina (8th), Arafat (9th), Muzdalifah (night of the 9th), then Mina and Makkah on the 10th (stoning, sacrifice, hair, Tawaf al-Ifadah), stoning on the 11th to 13th, and the Farewell Tawaf.', src: RN('hajj') },
      { n: 5, f: 'What do Tawaf and Sa’i involve, and what do they mean?', b: 'Tawaf is seven anticlockwise circuits of the Ka’bah: Allah is the centre of life. Sa’i is seven journeys between Safa and Marwa, remembering Hajar’s search for water and trust in Allah.', src: RN('hajj') },
      { n: 6, f: 'Why is the standing at Arafat the heart of Hajj?', b: 'Pilgrims stand from noon to sunset on the 9th in prayer and seeking forgiveness. It recalls the Day of Judgement and cannot be missed: “Hajj is Arafat”.', src: RN('hajj') },
      { n: 7, f: 'What happens at Muzdalifah and Mina?', b: 'At Muzdalifah pilgrims pray Maghrib and Isha together, spend the night in the open and gather pebbles. At Mina they stone the pillars (rejecting temptation) and make the sacrifice (recalling Ibrahim).', src: RN('hajj') },
      { n: 8, f: 'How does Umrah differ from Hajj?', b: 'Umrah can be done at any time of year and includes Ihram, Tawaf, Sa’i and cutting hair. It has no Mina, Arafat or Muzdalifah. It is highly recommended; scholars differ on whether it is obligatory.', src: RN('hajj') },
      { n: 9, f: 'How does Hajj promote the unity of the Ummah?', b: 'Pilgrims wear the same white clothes, so rank, wealth and race disappear, and perform the same rites together. It reminds them of the Day of Judgement, when all stand equal.', src: RN('hajj') },
    ]),
    ...sub(P1, 'jihad-9237', '3.1.2.7', [
      { n: 1, f: 'What does Jihad mean, and what does “fee sabilillah” mean?', b: 'Jihad means striving or struggle. Fee sabilillah means “in the path of Allah”. Most of Jihad is peaceful and takes place in daily life; it is not a synonym for war.', src: RN('jihad') },
      { n: 2, f: 'What are the four types of Jihad?', b: 'Bil-qalb (with the heart), Bil-lisan (with the tongue), Bil-yad (with the hand) and Bil-sayf (with the sword).', src: RN('jihad') },
      { n: 3, f: 'Give an example of Jihad with the heart and one with the tongue', b: 'Heart: controlling anger, envy or pride, and keeping sincere intention. Tongue: speaking truth, teaching, advising politely (16:125) or speaking against injustice.', src: RN('jihad') },
      { n: 4, f: 'Give an example of Jihad with the hand that does not involve fighting', b: 'Earning an honest living, caring for parents, giving to charity or helping neighbours. Effort with a good intention is worship.', src: RN('jihad') },
      { n: 5, f: 'What is Kitaal, and what are its main conditions?', b: 'Kitaal is armed fighting, one narrow part of Jihad. It needs a just cause (defence, never forcing religion), lawful authority, no transgression, and a readiness to accept peace.', src: RN('jihad') },
      { n: 6, f: 'What protections do the rules of Kitaal give?', b: 'Protection for non-combatants (women, children, the old, the sick, monks, worshippers), for property such as trees and crops, and humane treatment of prisoners (76:8).', src: RN('jihad') },
      { n: 7, f: 'What does Qur’an 2:190 teach about fighting?', b: '“Fight in the way of Allah those who fight against you, but do not transgress.” It permits defence only and sets limits; Allah does not like transgressors.', src: RN('jihad') },
      { n: 8, f: 'Why do many Muslims say Jihad of the heart is the foundation of the others?', b: 'Sincere intention and self-control give value to every other effort. The Hadith on changing wrong lists hand, tongue and heart, the heart being the weakest level but the base.', src: RN('jihad') },
      { n: 9, f: 'Who may decide that a community goes to armed defence?', b: 'A lawful leader or state, not individuals or private groups. Violence against civilians by self-appointed groups is rejected by Islam. Killing one innocent is like killing all humanity (5:32).', src: RN('jihad') },
    ]),
    ...sub(P1, 'festivals-and-commemorations-in-islam-9237', '3.1.2.8', [
      { n: 1, f: 'On what dates are Eid-ul-Fitr, Eid-ul-Adha and Ashura?', b: 'Eid-ul-Fitr: 1 Shawwal. Eid-ul-Adha: 10 Dhul Hijjah. Ashura: 10 Muharram. All move earlier through the seasons each year because the calendar is lunar.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 2, f: 'How is Eid-ul-Fitr observed?', b: 'Zakah al-Fitr is paid before the prayer; Muslims wash, wear their best clothes, eat dates and say the takbir; the two-rak’ah Eid prayer is held in congregation, with the sermon after it; then visits and gifts.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 3, f: 'What is the origin of Eid-ul-Adha?', b: 'The test of Ibrahim (AS), whom Allah asked to sacrifice his son Ismail. Both obeyed and Allah replaced the sacrifice with a ram (37:102-107). It falls the day after Arafat.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 4, f: 'How is the Qurbani meat shared?', b: 'In three parts: the family, relatives and friends, and the poor. Large animals can be shared by up to seven people. Qur’an 22:37 says it is piety that reaches Allah.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 5, f: 'How do Sunni and Shia Muslims understand Ashura?', b: 'Sunni: Allah saved Musa (AS) from Pharaoh, and the Prophet (pbuh) fasted, so Sunni Muslims fast. Shia: the death of Husayn (RA) at Karbala in 61 AH (680 CE), marked by mourning gatherings.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 6, f: 'What is Zakah al-Fitr, and how does it differ from yearly Zakah?', b: 'Food or its value given to the poor before the Eid-ul-Fitr prayer so they can enjoy the festival. It is not the yearly Zakah on qualifying wealth.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 7, f: 'What does the Ibn Majah hadith (1722) say about the two Eids?', b: 'The Prophet (pbuh) forbade fasting on both days: the Day of Fitr is when you break your fast, and on the Day of Adha you eat the meat of your sacrifices. He started with the prayer before the sermon.', src: RN('festivals-and-commemorations-in-islam') },
      { n: 8, f: 'Exam trap: is Ashura an Eid, and what does Fitr mean?', b: 'Ashura is a day of remembrance, not a feast: Sunni fast and Shia mourn. Fitr means breaking the fast, Adha means sacrifice, and fasting is forbidden on both Eids.', src: RN('festivals-and-commemorations-in-islam') },
    ]),

    // Paper 2 The life of Hazrat Muhammad (pbuh) and sources of authority
    ...sub(P2, 'life-teachings-hazrat-muhammad-9237', '3.2.1', [
      { n: 1, f: 'Give the key dates of Hazrat Muhammad’s (pbuh) life in Makkah', b: '570 born in Makkah. 610 first revelation in the Cave of Hira. 613 public preaching begins, followed by persecution. 615 first migration to Abyssinia. 619 Year of Sorrow.' },
      { n: 2, f: 'What happened in the Cave of Hira in 610?', b: 'The angel Jibril brought the first revelation, the opening verses of Surah al-Alaq, beginning “Read (Recite) in the name of your Lord who created”.' },
      { n: 3, f: 'What was the Year of Sorrow (619)?', b: 'The year in which his wife Khadijah and his uncle and protector Abu Talib both died.' },
      { n: 4, f: 'Why was the Hijra (622) important?', b: 'The migration from Makkah to Madinah allowed the first Muslim community and state to be established. It marks the start of the Islamic calendar.' },
      { n: 5, f: 'What was the Constitution of Madinah?', b: 'A document setting out the rights and duties of Muslims, Jews and other groups in Madinah as one community, with the Prophet as arbiter.' },
      { n: 6, f: 'What were the battles of Badr (624), Uhud (625) and the Trench (627)?', b: 'Badr: a smaller Muslim force defeated the Quraysh. Uhud: a setback after the archers left their post. Trench: a trench dug around Madinah withstood the Quraysh siege.' },
      { n: 7, f: 'What were the Treaty of Hudaybiyyah (628) and the conquest of Makkah (630)?', b: 'Hudaybiyyah was a ten-year truce with the Quraysh. In 630 the Muslims entered Makkah almost without fighting; a general amnesty was granted and the idols were removed from the Ka’bah.' },
      { n: 8, f: 'What did the Farewell Sermon (632) teach?', b: 'Equality regardless of race, the sanctity of life and property, the rights of women, the abolition of usury, and the ending of blood feuds.' },
    ]),
    ...sub(P2, 'sources-of-authority-9237', '3.2.2', [
      { n: 1, f: 'Put the four sources of authority in Islam in order', b: '1. The Qur’an. 2. The Hadith and Sunnah. 3. Ijma (consensus) and Qiyas (analogy), secondary sources used only where the Qur’an and Hadith give no explicit ruling.', src: SOA },
      { n: 2, f: 'Why is the Hadith needed alongside the Qur’an?', b: 'The Qur’an gives commands, but the Hadith and Sunnah supply the practical detail of how to carry them out. For example, the Qur’an commands prayer; the Sunnah shows its form.', src: SOA },
      { n: 3, f: 'What are the three stages in the history of the Qur’an?', b: 'Revelation (how it was received), preservation (how it was memorised and recorded) and compilation (how it was assembled into a single text).', src: SOA },
      { n: 4, f: 'What is the difference between isnad and matn?', b: 'Isnad: the chain of narrators transmitting a Hadith back to the Prophet (pbuh). Matn: the text or content of the Hadith itself. They are two separate tests of reliability.', src: SOA },
      { n: 5, f: 'What are the four categories of Hadith reliability?', b: 'Sahih (sound), Hasan (good), Daeef (weak) and Maudu (fabricated).', src: SOA },
      { n: 6, f: 'What is Ijma?', b: 'Consensus: scholars agree on a ruling where the Qur’an and Hadith are silent.', src: SOA },
      { n: 7, f: 'What is Qiyas?', b: 'Analogy: a new situation is reasoned about by comparison with a similar situation already addressed in the Qur’an or Hadith.', src: SOA },
      { n: 8, f: 'Exam trap: are Ijma and Qiyas equal in authority to the Qur’an and Hadith?', b: 'No. They are secondary sources that extend guidance to situations the primary sources do not explicitly cover.', src: SOA },
      { n: 9, f: 'Who compiled Sahih al-Bukhari and Sahih Muslim, and why are they significant?', b: 'Imam al-Bukhari and Imam Muslim, scholars of the 9th century CE. Sunni Muslims regard their two collections as the most reliable, because of the strict tests each compiler applied to every Hadith’s chain of narrators.' },
      { n: 10, f: 'What structure works for an “explain the importance of…” answer on sources of authority?', b: 'Point, evidence (a specific example), explain (how the Hadith supplies the detail the Qur’an does not), link (back to the source’s place in the hierarchy).', src: SOA },
    ]),
    ...sub(P2, 'pre-islamic-arabia-9237', '3.2.1.1', [
      { n: 1, f: 'What does Jahiliya mean?', b: 'The Age of Ignorance: ignorance of Allah’s guidance, not lack of intelligence. The Arabs had skill in poetry, trade and survival but no revealed book or moral law.', src: RN('pre-islamic-arabia') },
      { n: 2, f: 'Describe the religious beliefs of Pre-Islamic Arabia', b: 'Polytheism, with about 360 idols around the Ka’bah, including Hubal (in the Ka’bah), Al-Lat, Al-Uzza and Manat. Many believed Allah was Creator but used idols as go-betweens (39:3). There were also Jews, Christians and a few hanifs.', src: RN('pre-islamic-arabia') },
      { n: 3, f: 'What was a hanif? Name two', b: 'A person who rejected idols and followed the pure faith of Ibrahim (AS). Examples: Waraqa ibn Nawfal and Zayd ibn Amr.', src: RN('pre-islamic-arabia') },
      { n: 4, f: 'Describe the political organisation of Pre-Islamic Arabia', b: 'There was no central state; loyalty was to the tribe, led by a chief by persuasion and generosity. The Quraysh ruled Makkah by a council of clan leaders and guarded the Ka’bah. Blood feuds were common.', src: RN('pre-islamic-arabia') },
      { n: 5, f: 'Which moral practices of Pre-Islamic Arabia were admired and which were harmful?', b: 'Admired: courage, loyalty, generosity, keeping promises and hospitality. Harmful: female infanticide, gambling, drinking, usury, cheating, revenge and tribal pride (asabiyyah).', src: RN('pre-islamic-arabia') },
      { n: 6, f: 'How were women and the poor treated in Pre-Islamic Arabia?', b: 'Women had little protection or inheritance and men could marry without limit, with a few exceptions such as Khadija (RA). Orphans, widows and the poor were often cheated, and wealth was held by a few merchant families.', src: RN('pre-islamic-arabia') },
      { n: 7, f: 'What does Qur’an 17:31 forbid, and why was it needed?', b: '“Do not kill your children for fear of poverty; We provide for them and for you.” It banned infanticide, which was practised out of fear of poverty and shame at having girls (see also 81:8-9).', src: RN('pre-islamic-arabia') },
      { n: 8, f: 'Why did the Quraysh feel threatened by a call to worship one God?', b: 'It threatened their income from pilgrims to the idols, their status as guardians of the Ka’bah, and the tribal order. Equality before Allah also challenged class, slavery and usury.', src: RN('pre-islamic-arabia') },
    ]),
    ...sub(P2, 'early-life-of-hazrat-muhammad-9237', '3.2.1.2', [
      { n: 1, f: 'When and where was the Prophet (pbuh) born, and into which clan?', b: 'About 570 CE in Makkah, in the Year of the Elephant, into the Banu Hashim clan of the Quraysh. His father Abdullah had died before his birth.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 2, f: 'Who looked after the Prophet (pbuh) in childhood, in order?', b: 'The wet-nurse Halimah al-Sa’diyyah in the desert, his mother Aminah (died at Abwa when he was about six), his grandfather Abdul Mutalib (died when he was about eight), then his uncle Abu Talib.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 3, f: 'What was the role of Abu Talib in the Prophet’s life?', b: 'He was guardian from about eight, took him to Syria with a caravan and protected him for many years, but he never accepted Islam.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 4, f: 'Who was Bahira, and what is the status of his story?', b: 'A Christian monk of Busra who met the boy of about twelve on the Syrian caravan, recognised signs of prophethood and warned Abu Talib to protect him. It is a tradition, not stated in the Qur’an.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 5, f: 'How did the Prophet (pbuh) come to marry Khadija (RA)?', b: 'He traded for her in Syria, and her servant Maysarah reported his honesty. She, a wealthy widow of about forty, proposed. They married about 595 CE, when he was about twenty-five, and the marriage lasted twenty-five years.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 6, f: 'What two titles did the Makkans give the Prophet (pbuh), and what do they mean?', b: 'Al-Amin (the trustworthy) and as-Sadiq (the truthful). People left their valuables with him, and he was known for honest weights and fair dealing as a merchant.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 7, f: 'How did the Prophet (pbuh) settle the Black Stone dispute?', b: 'When the clans rebuilt the Ka’bah and argued over who would lift the stone, he placed it on a cloak and a leader from each clan held a corner. It ended peacefully and showed wisdom, fairness and trust.', src: RN('early-life-of-hazrat-muhammad') },
      { n: 8, f: 'What does Qur’an 68:4 say about the Prophet’s character?', b: '“And indeed, you are of a great moral character.” It shows his character as the model for believers. Qur’an 10:16 adds that his people had known him for a lifetime before revelation.', src: RN('early-life-of-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-call-to-prophethood-nabuat-9237', '3.2.1.3', [
      { n: 1, f: 'Describe the first revelation in the Cave of Hira', b: 'About 610 CE, in Ramadhan, aged 40, Jibril (AS) appeared and said “Iqra” (Read). The Prophet replied “I am not one who can read”, three times, and each time Jibril held him tightly, then recited 96:1-5.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 2, f: 'What do the first verses of revelation (96:1-5) stress?', b: 'Reading and knowledge: recite in the name of your Lord who created, who taught by the pen and taught man what he knew not. They show Allah as Creator and the value of learning.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 3, f: 'How did the Prophet (pbuh) react to the first revelation?', b: 'With fear and confusion. He came down trembling and said to Khadija (RA), “Cover me, cover me.” He claimed no greatness, which shows his honesty and supports the belief that revelation came from Allah.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 4, f: 'What was the role of Khadija (RA) in the call?', b: 'She comforted him (“Allah will never disgrace you”), named his qualities, believed him as the first person to accept Islam, and took him to Waraqa.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 5, f: 'Who was Waraqa ibn Nawfal, and what did he say?', b: 'Khadija’s cousin, an old blind Christian who had studied scripture. He said it was the same angel who came to Musa (AS), warned that the people would drive Muhammad out, and promised support if he lived.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 6, f: 'Who were the first believers?', b: 'Khadija (RA) was the first, then Ali (RA), a boy of about ten, Zayd ibn Harithah (RA), the freed servant, and Abu Bakr (RA), the closest friend and first adult man.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 7, f: 'What was the fatrah, and how did revelation resume?', b: 'The fatrah was a pause in revelation after the first message. It resumed with 74:1-2, “arise and warn”.', src: RN('the-call-to-prophethood-nabuat') },
      { n: 8, f: 'Exam trap: how do Hira and Thawr differ?', b: 'Hira is the cave of the first revelation, on Jabal al-Nur. Thawr is the cave where the Prophet (pbuh) and Abu Bakr (RA) sheltered during the Hijrah.', src: RN('the-call-to-prophethood-nabuat') },
    ]),
    ...sub(P2, 'early-preaching-of-islam-9237', '3.2.1.4', [
      { n: 1, f: 'What were the two phases of the early preaching?', b: 'Private (about three years): personal invitation to trusted people and secret meetings. Public: a meal for the family, the call from Mount Safa and open preaching at the Ka’bah, on Allah’s command (26:214; 15:94).', src: RN('early-preaching-of-islam') },
      { n: 2, f: 'Where did early Muslims meet in secret, and who were some of the early believers?', b: 'The house of al-Arqam, near Safa. Believers included Khadija, Ali, Zayd and Abu Bakr, and also the poor and slaves such as Bilal and Ammar and his parents.', src: RN('early-preaching-of-islam') },
      { n: 3, f: 'What happened at Mount Safa?', b: 'The Prophet (pbuh) called the Quraysh, who agreed he had never lied, and warned them. Abu Lahab insulted him, and Surah 111 followed.', src: RN('early-preaching-of-islam') },
      { n: 4, f: 'What did the call to Tawhid and the rejection of idols mean in practice?', b: 'Allah alone creates and is worshipped, idols are only names (53:23), no go-between is needed, and everyone answers on the Day of Judgement. It threatened Quraysh tradition, income and status.', src: RN('early-preaching-of-islam') },
      { n: 5, f: 'Name four rights given to women by early Islamic teaching, with sources', b: 'A ban on infanticide (17:31), equal reward for deeds (3:195; 33:35), a share of inheritance (4:7; 4:11), and owning property and receiving the mahr (4:4). Consent in marriage and respect for mothers also feature.', src: RN('early-preaching-of-islam') },
      { n: 6, f: 'In what stages was alcohol banned?', b: 'Stage 1: great sin, some benefit, sin greater (2:219). Stage 2: do not pray intoxicated (4:43). Stage 3: complete ban, as the work of Satan (5:90-91).', src: RN('early-preaching-of-islam') },
      { n: 7, f: 'Give reasons for the ban on alcohol and gambling', b: 'They cause hatred and enmity between people, distract from remembrance of Allah and prayer, waste money and harm families (5:90-91).', src: RN('early-preaching-of-islam') },
      { n: 8, f: 'What does Surah al-Fatihah (1:1-7) show about the early message?', b: 'Allah’s mercy, that He is Lord of the worlds and Sovereign of the Day of Recompense, worship of Him alone, and the need for guidance to the straight path. It is recited in every prayer.', src: RN('early-preaching-of-islam') },
    ]),
    ...sub(P2, 'opposition-to-hazrat-muhammad-9237', '3.2.1.5', [
      { n: 1, f: 'Give four types of reason why the Quraysh opposed the Prophet (pbuh)', b: 'Religious (Tawhid rejected the ancestors’ idols), economic (pilgrim trade), political and tribal (loss of leadership) and social (equality threatened the rich over slaves and the poor).', src: RN('opposition-to-hazrat-muhammad') },
      { n: 2, f: 'Who were Abu Lahab and Abu Jahl?', b: 'Abu Lahab was the Prophet’s uncle who insulted him at Safa (Surah 111). Abu Jahl was a leading enemy who proposed the plot to kill him.', src: RN('opposition-to-hazrat-muhammad') },
      { n: 3, f: 'How did the Quraysh treat weak Muslims, and who was the first martyr?', b: 'They tortured them, including Bilal, Sumayyah, Yasir and Ammar. Sumayyah was the first martyr. About 615 CE some Muslims migrated to Abyssinia, protected by the Negus.', src: RN('opposition-to-hazrat-muhammad') },
      { n: 4, f: 'What was the boycott of Banu Hashim?', b: 'About 616 to 619 CE, for three years, the Quraysh cut off trade, marriage and contact with Banu Hashim and Banu Muttalib, who lived in the valley of Abu Talib. It caused hunger and illness until some Quraysh cancelled it.', src: RN('opposition-to-hazrat-muhammad') },
      { n: 5, f: 'What was the Year of Sorrow?', b: 'About 619 CE, when Abu Talib and Khadija (RA) both died. He lost his protector and comfort, and the Quraysh felt free to attack him more.', src: RN('opposition-to-hazrat-muhammad') },
      { n: 6, f: 'What happened at Ta’if?', b: 'The Prophet (pbuh) and Zayd (RA) sought support from Thaqif, who rejected him and had children and slaves stone him. He prayed to Allah, and when the angel of the mountains offered to crush Makkah, he refused.', src: RN('opposition-to-hazrat-muhammad') },
      { n: 7, f: 'Describe the plot to kill the Prophet (pbuh)', b: 'At the Dar al-Nadwa, Abu Jahl proposed that one young man from each clan strike together to share the blame. Allah informed the Prophet (8:30); Ali (RA) slept in his bed and he left with Abu Bakr (RA).', src: RN('opposition-to-hazrat-muhammad') },
      { n: 8, f: 'What does Surah 111 teach?', b: 'Allah defends His Messenger: the hands of Abu Lahab are ruined, his wealth will not avail him, and his wife, the carrier of firewood, shares responsibility. Family ties do not protect anyone from the truth.', src: RN('opposition-to-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-ascension-of-hazrat-muhammad-9237', '3.2.1.6', [
      { n: 1, f: 'What are the Isra and the Mi’raj?', b: 'The Isra is the night journey from al-Masjid al-Haram in Makkah to al-Masjid al-Aqsa in Jerusalem, on the Buraq. The Mi’raj is the ascent through the heavens.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 2, f: 'Describe the sequence of the night', b: 'Jibril washed the Prophet’s heart with Zamzam; Buraq carried him to al-Aqsa, where he led the prophets in prayer; he ascended through seven heavens to Sidrat al-Muntaha, was shown Paradise and the Fire, and received the five daily prayers.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 3, f: 'How did the number of daily prayers come to be five?', b: 'Fifty were commanded at first. Musa (AS) advised the Prophet (pbuh) to ask for a reduction, and after several returns it became five, with the reward of fifty remaining.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 4, f: 'Which prophets did the Prophet (pbuh) meet in the first and seventh heavens, according to the traditional account?', b: 'Adam (AS) in the first heaven and Ibrahim (AS) in the seventh. Others include Isa and Yahya (2nd), Yusuf (3rd), Idris (4th), Harun (5th) and Musa (6th).', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 5, f: 'How did the Quraysh and Abu Bakr (RA) respond to the news?', b: 'Some mocked it and some wavered in faith. They asked him to describe Jerusalem, which he did accurately. Abu Bakr (RA) said “If he said it, then it is true” and was named as-Siddiq.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 6, f: 'Why was the timing of the journey significant?', b: 'It came after the Year of Sorrow and the rejection at Ta’if, as a comfort and honour from Allah when the Prophet (pbuh) was most in need.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 7, f: 'What does Qur’an 17:1 teach?', b: 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings He blessed, to show him His signs. He is the Hearing, the Seeing.', src: RN('the-ascension-of-hazrat-muhammad') },
      { n: 8, f: 'What are the different views on the Isra and Mi’raj?', b: 'The majority of scholars hold it was in body and spirit. Some say it was a vision or spiritual journey. Both views agree it was a miracle and a sign from Allah.', src: RN('the-ascension-of-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-hijrah-and-the-madni-period-9237', '3.2.1.7', [
      { n: 1, f: 'What were the two pledges of Aqaba?', b: 'First: twelve men promised not to commit shirk, theft, adultery, kill children or slander, and Mus’ab ibn Umair was sent to teach. Second: more than seventy men and two women promised to protect the Prophet (pbuh) as their own families.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 2, f: 'Describe the journey of the Hijrah', b: 'Ali (RA) slept in the Prophet’s bed on the night of the plot; the Prophet (pbuh) and Abu Bakr (RA) hid three nights in the cave of Thawr, then travelled with a guide. They reached Quba, then Madinah, in 622 CE.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 3, f: 'What were the roles of Ali (RA) and Abu Bakr (RA) in the Hijrah?', b: 'Ali slept in the Prophet’s bed and returned the trusts left with him, showing courage and honesty. Abu Bakr prepared camels and a guide and travelled with the Prophet, showing loyalty and planning.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 4, f: 'What happened at the cave of Thawr and with Suraqa?', b: 'At the cave mouth the Prophet said “Do not grieve; indeed Allah is with us” (9:40). Suraqa chased them for the reward of a hundred camels but his horse sank and he turned back.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 5, f: 'What was the first mosque in Islam, and how does it differ from the Prophet’s Mosque in Madinah?', b: 'Quba, built on arrival at the edge of Madinah. The Prophet’s Mosque was built on land of two orphans that was paid for, and was the centre of community life: prayer, learning, courts and meetings.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 6, f: 'List four actions of the Prophet (pbuh) as a statesman in Madinah', b: 'He built the mosque as the community’s centre, created brotherhood between the Muhajirun and the Ansar, agreed the Charter of Madinah, and organised defence and relations with other tribes.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 7, f: 'What were the main terms of the Charter of Madinah?', b: 'One Ummah, ending the Aws and Khazraj feud; Jewish tribes kept their religion; joint defence; no help for the Quraysh; help for the oppressed; disputes referred to Allah and the Prophet; Madinah a sacred area.', src: RN('the-hijrah-and-the-madni-period') },
      { n: 8, f: 'Who hosted the Prophet (pbuh) in Madinah, and which verse speaks of a mosque founded on righteousness?', b: 'Abu Ayyub al-Ansari (RA) hosted him. Qur’an 9:108 speaks of a mosque founded on righteousness from the first day; many scholars say Quba, others the Prophet’s Mosque.', src: RN('the-hijrah-and-the-madni-period') },
    ]),
    ...sub(P2, 'supporters-of-hazrat-muhammad-9237', '3.2.1.8', [
      { n: 1, f: 'What do Ansaar, Muhajirun and Sahabah mean?', b: 'Ansaar: the helpers, Muslims of Madinah. Muhajirun: the emigrants from Makkah. Sahabah: the companions of the Prophet (pbuh).', src: RN('supporters-of-hazrat-muhammad') },
      { n: 2, f: 'How did the Ansaar support the Muhajirun?', b: 'They shared homes and food, paired as brothers (mu’akhat) and offered a share of property and orchards. Sa’d ibn al-Rabi’ offered half his wealth to Abdur Rahman ibn Awf, who asked only to be shown the market.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 3, f: 'What does Qur’an 59:9 say about the Ansaar?', b: 'They love those who emigrated to them and give them preference over themselves, even if they are in need. This quality is called ithar.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 4, f: 'What is Abu Ayyub al-Ansari (RA) remembered for?', b: 'He hosted the Prophet (pbuh) in Madinah for about seven months while the mosque was built, a model of hospitality. He later died at Constantinople, about 52 AH.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 5, f: 'Who was Hamza (RA), and why was he called Master of the Martyrs?', b: 'The uncle and foster brother of the Prophet (pbuh), called the Lion of Allah. His conversion strengthened Islam, he fought at Badr and was martyred at Uhud in 3 AH.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 6, f: 'What did Talha (RA) do at Uhud?', b: 'He shielded the Prophet (pbuh) and was wounded, protecting his life at a dangerous moment. He was one of the ten promised Paradise, known for sacrifice.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 7, f: 'Who was Zubair (RA)?', b: 'The Prophet’s cousin and the son of Safiyyah (RA), an early convert as a youth, called the Prophet’s hawari (faithful helper). He fought in many battles and was one of the ten promised Paradise.', src: RN('supporters-of-hazrat-muhammad') },
      { n: 8, f: 'What does the hadith in Tirmidhi 3675 show about Umar (RA) and Abu Bakr (RA)?', b: 'When told to give charity, Umar gave half his wealth, hoping to outdo Abu Bakr. Abu Bakr brought everything, leaving “Allah and His Messenger”. Umar said he would never do better than Abu Bakr.', src: RN('supporters-of-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-battles-fought-by-hazrat-muhammad-9237', '3.2.1.9', [
      { n: 1, f: 'Put the main battles and events in order, with dates', b: 'Badr (2 AH, 624), Uhud (3 AH, 625), the Trench (5 AH, 627), Hudaibiyah (6 AH, 628), Khaibar (7 AH), Fath-e-Makkah and Hunayn (8 AH, 630), Aam ul wafood (9 AH) and the Farewell Pilgrimage (10 AH, 632).', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 2, f: 'Why was Badr important?', b: 'About 313 Muslims defeated about 1,000 Quraysh. Qur’an 8:41 calls it the day of criterion (Furqan). Victory came from Allah, the community’s confidence rose, and captives were treated well.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 3, f: 'Why did the Muslims suffer losses at Uhud?', b: 'The archers on the hill left their post for spoils and Khalid ibn al-Walid attacked from behind. About seventy Muslims were martyred, including Hamza (RA). Lessons: obey commands, do not be distracted by spoils, be patient.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 4, f: 'How did the Muslims defend Madinah at the Trench (627)?', b: 'Salman al-Farsi (RA) proposed digging a trench. About 3,000 Muslims faced about 10,000 allies; the siege, cold wind and mistrust broke the alliance. The Quraysh never attacked in force again.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 5, f: 'What were the terms of the Treaty of Hudaibiyah?', b: 'A ten-year truce; the Muslims return next year for three days; Quraysh who joined the Muslims without permission are returned, but not Muslims who left; tribes are free to ally with either side.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 6, f: 'Why is Hudaibiyah called a “clear conquest” (48:1)?', b: 'Although some clauses seemed one-sided, the peace brought recognition of the Muslims and allowed Islam to spread. The Pledge of Ridwan under a tree (48:18) took place there. Do not describe it as a defeat.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 7, f: 'What happened at Fath-e-Makkah in 8 AH?', b: 'About 10,000 Muslims entered Makkah almost without fighting after the Quraysh breached the treaty. The idols were removed (17:81), Bilal gave the adhan at the Kaaba, and a general amnesty was granted.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 8, f: 'What do Hunayn, Aam ul wafood and the Farewell Pilgrimage show?', b: 'Hunayn: about 12,000 Muslims were ambushed, and 9:25 rebukes pride in numbers. Aam ul wafood (9 AH) was the Year of Delegations. At the Farewell Pilgrimage (10 AH) came the Final Sermon and 5:3.', src: RN('battles-fought-by-hazrat-muhammad') },
      { n: 9, f: 'What rules of war are taught in the notes?', b: 'No harm to women, children, the elderly or worshippers; no needless destruction of crops or trees; humane treatment of captives; accept peace when offered (8:61).', src: RN('battles-fought-by-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-legacy-and-lessons-of-hazrat-muhammad-9237', '3.2.1.10', [
      { n: 1, f: 'When and where was the Final Sermon given?', b: 'On the ninth of Dhul-Hijjah, 10 AH (632 CE), at Arafat during the Farewell Pilgrimage. Those present were told to pass the message on to those absent. The Prophet (pbuh) died about three months later.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 2, f: 'Give five teachings of the Final Sermon', b: 'Life, property and honour are sacred; return trusts; interest and blood feuds are cancelled; treat women well; only taqwa makes one person better than another; hold fast to the Qur’an and Sunnah.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 3, f: 'What does the Final Sermon teach about racial and tribal pride?', b: 'It is cancelled: no Arab is above a non-Arab, nor a white person above a black person, except by taqwa. Muslims are brothers.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 4, f: 'What does Qur’an 5:3 say, and why is it linked to Arafat?', b: '“This day I have perfected for you your religion and completed My favour upon you.” The guidance is complete; the verse is linked to Arafat. It also has mercy built into the rules (“Allah is Forgiving and Merciful”).', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 5, f: 'What does Islam teach about the treatment of parents?', b: 'Good treatment, never saying “uff” and lowering the wing of humility (17:23-24). The Hadith says “your mother” three times, then “your father”. Obedience stops at disobeying Allah, but kindness continues (31:15).', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 6, f: 'What does Islam teach about justice, with an example from the Prophet’s life?', b: 'Stand firm in justice even against yourselves, parents and relatives (4:135), and even towards enemies (5:8). He refused to excuse a noble woman’s theft, saying he would apply the same rule to his own daughter Fatima.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 7, f: 'What does Islam teach about honesty, with an example from the Prophet’s life?', b: 'Truthfulness leads to righteousness and righteousness to Paradise (Hadith). He was called al-Amin and al-Sadiq, and Ali (RA) returned the deposits left with him at the Hijrah.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
      { n: 8, f: 'What does Islam teach about patience, with an example?', b: 'Allah is with the patient (2:153) and rewards them without account (39:10). Examples: Ta’if, the boycott, bereavements, and forgiveness at Makkah. Patience is active: planning, effort and prayer.', src: RN('legacy-and-lessons-of-hazrat-muhammad') },
    ]),
    ...sub(P2, 'the-revelation-and-compilation-of-the-quran-9237', '3.2.2.1', [
      { n: 1, f: 'What are the three stages in the history of the Qur’an as the final revelation?', b: 'Revealed through Jibril (AS) over about 23 years; preserved by memory, writing and review in the Prophet’s lifetime; compiled under Abu Bakr (RA) and copied to a standard text under Uthman (RA).', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 2, f: 'Why was the Qur’an revealed gradually?', b: 'To strengthen the Prophet’s heart (25:32), to answer questions and events as they arose, to make it easy to memorise, and to introduce laws step by step, as with alcohol.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 3, f: 'How was the Qur’an preserved in the Prophet’s lifetime?', b: 'Companions memorised it (huffaz), scribes such as Zayd ibn Thabit wrote it on leather, bones, palm stalks and stones, it was reviewed yearly with Jibril, twice in the last year, and recited in daily prayers.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 4, f: 'Why and how was the Qur’an first compiled under Abu Bakr (RA)?', b: 'Many huffaz were martyred at Yamama, and Umar (RA) feared parts might be lost. Zayd ibn Thabit collected it, accepting a verse only if written in the Prophet’s presence and confirmed by witnesses.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 5, f: 'Who kept the sheets of the Qur’an after Abu Bakr (RA)?', b: 'Umar (RA), then Hafsa (RA), whose sheets Uthman (RA) later borrowed.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 6, f: 'Why did Uthman (RA) have standard copies made?', b: 'Hudhayfa ibn al-Yaman warned of differences in recitation in newly conquered regions. Zayd and three Quraysh wrote copies, using the Quraysh dialect where they differed, and sent them to the main regions.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 7, f: 'Exam trap: did Uthman (RA) change the text of the Qur’an?', b: 'No. He standardised copies from Abu Bakr’s sheets and burned other materials to prevent confusion. Keep the two compilations separate: Abu Bakr gathered the text; Uthman standardised it.', src: RN('revelation-and-compilation-of-the-quran') },
      { n: 8, f: 'Which verses show that the Qur’an is protected and final?', b: 'Qur’an 15:9: “We will be its guardian”. 33:40: Muhammad is the seal of the prophets. 5:3: the religion is completed. 5:48: it confirms earlier scripture.', src: RN('revelation-and-compilation-of-the-quran') },
    ]),
    ...sub(P2, 'the-features-and-use-of-the-quran-9237', '3.2.2.2', [
      { n: 1, f: 'Give the basic features of the Qur’an', b: '114 surahs, arranged roughly from longest to shortest, not in order of revelation; 30 equal parts (juz’); revealed in Arabic; every surah except at-Tawbah (9) opens with the Bismillah.', src: RN('features-and-use-of-the-quran') },
      { n: 2, f: 'What is the difference between Makki and Madni surahs?', b: 'Makki surahs were revealed before the Hijrah, to a persecuted minority, and stress Tawhid, prophethood and the Hereafter. Madni surahs came after the Hijrah and give law, worship, family and trade rules.', src: RN('features-and-use-of-the-quran') },
      { n: 3, f: 'Give examples of Makki and Madni surahs', b: 'Makki: al-Alaq, al-Kafirun, al-Kahf. Madni: al-Baqarah, Al Imran, an-Nisa, al-Ma’idah, an-Nur. The division is by time (before or after the Hijrah), not strictly by place.', src: RN('features-and-use-of-the-quran') },
      { n: 4, f: 'What is i’jaz? Give three lines of evidence', b: 'The miraculous, inimitable quality of the Qur’an: its eloquence, the challenge to produce a surah like it (2:23), the unlettered Prophet (29:48), its consistency (4:82) and its true accounts and predictions.', src: RN('features-and-use-of-the-quran') },
      { n: 5, f: 'What does the infallibility of the Qur’an mean, and what verses support it?', b: 'It is free from error and change. “Falsehood cannot approach it” (41:42) and “We will be its guardian” (15:9). Translations and commentaries can contain errors; the Qur’an itself cannot.', src: RN('features-and-use-of-the-quran') },
      { n: 6, f: 'How do Muslims use the Qur’an?', b: 'In worship (al-Fatiha in every rak’ah), as the first source of Shariah, for guidance on family, money and character, for learning and memorisation, for comfort in grief and fear, and in teaching.', src: RN('features-and-use-of-the-quran') },
      { n: 7, f: 'How do Muslims treat the Qur’an with respect?', b: 'They handle it clean, keep it in a high place and not on the floor, recite it with tajwid (73:4), listen with attention (7:204), and above all act on it.', src: RN('features-and-use-of-the-quran') },
      { n: 8, f: 'What does Qur’an 56:75-80 teach?', b: 'A solemn oath that this is a noble Qur’an, in a well-protected Register, which none touch except the purified, a revelation from the Lord of the worlds. It is used for the rule on wudu when touching the text.', src: RN('features-and-use-of-the-quran') },
    ]),
    ...sub(P2, 'the-hadith-and-sunnah-as-a-source-of-shariah-9237', '3.2.2.3', [
      { n: 1, f: 'Define Hadith, Sunnah and Shariah', b: 'Hadith: a report of what the Prophet said, did, approved or was like. Sunnah: his way and example, recorded in the Hadith. Shariah: the law or path of Islam, drawn from the Qur’an and Sunnah first, then Ijma and Qiyas.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 2, f: 'In what four ways does the Hadith relate to the Qur’an?', b: 'It explains (prayer: “Pray as you have seen me praying”), specifies (a murderer does not inherit), adds guidance not in the Qur’an, and confirms Qur’anic teaching.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 3, f: 'Give Qur’anic evidence that Muslims should follow the Sunnah', b: 'Obey Allah and the Messenger (4:59); whoever obeys the Messenger has obeyed Allah (4:80); an excellent pattern (33:21); follow him if you love Allah (3:31); take what he gives (59:7).', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 4, f: 'What is the Hadith of Mu’adh ibn Jabal about?', b: 'He said he would judge by the Book of Allah, then the Sunnah, then his own reasoning, and the Prophet approved. It shows the order of authority: Qur’an first, Sunnah second.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 5, f: 'What are the kinds of Sunnah?', b: 'Sayings (what he said), actions (what he did), approvals (what he saw and did not forbid) and character (how he was described). Some Sunnah is obligatory and some recommended.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 6, f: 'What does the Sunnah add to the Qur’an for Salah and Zakah?', b: 'Salah: the times, form, rak’ahs and call to prayer. Zakah: the minimum amount (nisab) and rates. The Qur’an gives only the commands.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 7, f: 'What does Qur’an 53:1-6 say about the Prophet’s teaching?', b: 'He has not strayed or erred, nor does he speak from his own inclination; it is a revelation taught by Jibril. Many scholars use it to support the Sunnah; all agree it proves the Qur’an is revelation.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
      { n: 8, f: 'Evaluate the claim “The Qur’an is enough”', b: 'For: the Qur’an is complete and protected. Against: it commands obedience to the Messenger and lacks the details of prayer and Zakah. The Qur’an is the foundation, but it points to the Sunnah for practice.', src: RN('hadith-and-sunnah-as-source-of-shariah') },
    ]),
    ...sub(P2, 'the-compilation-and-categorisation-of-hadith-9237', '3.2.2.4', [
      { n: 1, f: 'Why were Hadith tested for reliability?', b: 'The Prophet warned that whoever lies about him intentionally will take his place in the Fire (Bukhari 3461). Reports were fabricated for political and sectarian reasons, and honest narrators sometimes forgot details.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 2, f: 'What are the Isnad and the Matn, and what is checked in each?', b: 'Isnad is the chain of narrators: did each meet the previous one, were they upright, with good memory, and is the chain complete? Matn is the text: does it contradict the Qur’an, stronger Hadith, sense or history?', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 3, f: 'Define Sahih and Hasan Hadith', b: 'Sahih (sound): a complete chain of upright narrators with excellent memory and no hidden defect. Hasan (good): as Sahih, but a narrator has a slightly weaker memory.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 4, f: 'Define Da’if and Maudu’ Hadith', b: 'Da’if (weak): a condition is missing, such as a broken chain, a doubtful narrator or a defect. Maudu’ (fabricated): invented, or with a known liar in the chain, and rejected.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 5, f: 'Who were Imam Bukhari and Imam Muslim?', b: 'Muhammad ibn Ismail al-Bukhari (194-256 AH) of Bukhara compiled Sahih al-Bukhari over about sixteen years. Muslim ibn al-Hajjaj of Nishapur, his student, compiled Sahih Muslim. Together they are the Sahihayn.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 6, f: 'How did Bukhari’s and Muslim’s conditions for accepting narrators differ?', b: 'Bukhari required that narrators had met. Muslim accepted that they were contemporaries and could have met.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 7, f: 'Name the six major Hadith collections', b: 'Bukhari, Muslim, Abu Dawud, al-Tirmidhi, al-Nasa’i and Ibn Majah. Other works include Malik’s al-Muwatta and Ahmad ibn Hanbal’s Musnad.', src: RN('compilation-and-categorisation-of-hadith') },
      { n: 8, f: 'What does Bukhari 3461 teach?', b: 'Convey my teachings even if a single sentence; accounts of Bani Israel may be told; and whoever lies about the Prophet intentionally will take his place in the Fire. This explains the need for Isnad and Matn.', src: RN('compilation-and-categorisation-of-hadith') },
    ]),
    ...sub(P2, 'the-different-schools-of-thought-in-islam-9237', '3.2.2.5', [
      { n: 1, f: 'What is a madhhab, and how do ijtihad and taqlid differ?', b: 'A madhhab is a school of law with its own method for deriving rulings. Ijtihad is independent reasoning by a qualified scholar; taqlid is following a school or scholar.', src: RN('different-schools-of-thought-in-islam') },
      { n: 2, f: 'Name the five major law schools and their founders', b: 'Hanafi (Abu Hanifa), Maliki (Malik ibn Anas), Shafi’i (al-Shafi’i), Hanbali (Ahmad ibn Hanbal) and Ja’fari (Ja’far al-Sadiq).', src: RN('different-schools-of-thought-in-islam') },
      { n: 3, f: 'What are four causes of difference between the schools?', b: 'Words with more than one meaning (such as quru’ in 2:228), Hadith known in different places, different methods of reasoning, and different circumstances.', src: RN('different-schools-of-thought-in-islam') },
      { n: 4, f: 'What was the method of the Maliki and Shafi’i schools?', b: 'Maliki: the practice of Madinah and maslahah, with al-Muwatta. Shafi’i: Qur’an, Sunnah, Ijma and Qiyas in order, with al-Shafi’i’s al-Risala.', src: RN('different-schools-of-thought-in-islam') },
      { n: 5, f: 'What was the method of the Hanafi and Hanbali schools?', b: 'Hanafi: Qiyas, istihsan and custom. Hanbali: Hadith and the companions first, with little analogy, and Ahmad ibn Hanbal’s al-Musnad.', src: RN('different-schools-of-thought-in-islam') },
      { n: 6, f: 'What is distinctive about the Ja’fari school?', b: 'It is the school of the Twelver Shi’a, drawing on the Imams of the Ahl al-Bayt and on reason (’aql), with centres in Iran and Iraq. Ja’fari Muslims often combine prayers and prostrate on natural earth or a clay tablet.', src: RN('different-schools-of-thought-in-islam') },
      { n: 7, f: 'What is agreed between the schools, and what is the role of the schools?', b: 'All accept the Qur’an, Sunnah and Five Pillars; differences are in details such as hand position in prayer. They give guidance, consistency, flexibility and protect the sources. They are not separate religions.', src: RN('different-schools-of-thought-in-islam') },
      { n: 8, f: 'How does Qur’an 4:59 relate to the schools?', b: 'It tells believers to obey Allah and the Messenger and those in authority, and, if they disagree, to refer to Allah and the Messenger. It shows the sources every school uses and expects disagreement.', src: RN('different-schools-of-thought-in-islam') },
    ]),
    ...sub(P2, 'ijma-and-qiyas-as-a-source-of-shariah-9237', '3.2.2.6', [
      { n: 1, f: 'What is Ijma, and who takes part in it?', b: 'The agreement of qualified scholars (mujtahidun) of a period on a religious ruling, after the Prophet (pbuh), on matters not settled by a clear text. Ordinary people are not counted.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 2, f: 'Give examples of Ijma', b: 'Choosing Abu Bakr (RA) as first caliph, collecting the Qur’an into one book, praying Taraweeh behind one imam under Umar (RA), and the grandmother’s one-sixth share.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 3, f: 'What are the four parts of a Qiyas, with their Arabic terms?', b: 'Asl (the original case with a ruling in the Qur’an or Sunnah), far’ (the new case), hukm (the ruling) and ’illa (the reason shared by both cases).', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 4, f: 'Give the steps of Qiyas', b: 'Find the original case; identify its reason; check that the new case shares it; give the new case the same ruling.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 5, f: 'Give a worked example of Qiyas', b: 'Wine is forbidden (5:90); the shared reason is that it clouds the mind and harms the person, so a modern drug is forbidden too. Likewise “uff” to parents (17:23) gives the ruling against shouting at or hitting them.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 6, f: 'What is the order of the four sources, and may Ijma or Qiyas contradict the Qur’an or Sunnah?', b: 'Qur’an, Sunnah, Ijma, Qiyas. No: Ijma and Qiyas are tested by the first two and must never contradict them, as in the Hadith of Mu’adh ibn Jabal.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 7, f: 'How do the schools view Qiyas and Ijma?', b: 'Hanafi use reasoning widely, with qiyas and istihsan; Maliki add the practice of Madinah; Shafi’i accept Qiyas under strict rules; Hanbali use it only where necessary; Ja’fari use reason (’aql) instead of Sunni qiyas.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
      { n: 8, f: 'How is Qur’an 4:115 used, and what care is needed?', b: 'Many scholars use “follows other than the way of the believers” as evidence for Ijma. Do not say the verse itself states the rule; scholars derive it from the verse.', src: RN('ijma-and-qiyas-as-source-of-shariah') },
    ]),
    ...sub(P2, 'the-use-of-shariah-in-everyday-life-9237', '3.2.2.7', [
      { n: 1, f: 'What are the five grades of action in Shariah?', b: 'Wajib or fard (required), mustahabb (recommended), mubah (permitted), makruh (disliked) and haram (forbidden).', src: RN('use-of-shariah-in-everyday-life') },
      { n: 2, f: 'What do halal and haram cover, and what is the basic rule?', b: 'Halal is lawful, haram unlawful, covering income and conduct as well as food. Everything is halal unless a text forbids it; doubtful matters are to be avoided.', src: RN('use-of-shariah-in-everyday-life') },
      { n: 3, f: 'Which foods are forbidden in the Qur’an (2:173; 5:3)?', b: 'Dead animals, flowing blood, pork, food dedicated to other than Allah, and animals killed by strangling, a blow, a fall or goring. Alcohol and intoxicants are forbidden by 5:90.', src: RN('use-of-shariah-in-everyday-life') },
      { n: 4, f: 'What are the conditions of halal slaughter (dhabihah)?', b: 'A healthy animal, the name of Allah said, the throat cut quickly with a very sharp knife, and the blood drained, with kindness and sparing suffering.', src: RN('use-of-shariah-in-everyday-life') },
      { n: 5, f: 'What exception does necessity allow in the dietary laws?', b: 'A person forced by hunger may eat forbidden food, with no desire to disobey and no excess (2:173).', src: RN('use-of-shariah-in-everyday-life') },
      { n: 6, f: 'What are the dress laws for men and women, according to most scholars?', b: 'Men cover at least from navel to knees, lower the gaze (24:30) and avoid silk and gold. Women cover the body except the face and hands and draw the head covering over the chest (24:31). Details vary by culture.', src: RN('use-of-shariah-in-everyday-life') },
      { n: 7, f: 'What do parents do to give a religious upbringing and good character?', b: 'Teach the Shahadah and belief, give a good name, teach prayer from about seven, teach the Qur’an, take children to the mosque, set an example, and teach honesty and kindness using Luqman’s advice (31:13-19).', src: RN('use-of-shariah-in-everyday-life') },
      { n: 8, f: 'What does Sahih al-Bukhari 5027 say?', b: '“The best among you are those who learn the Qur’an and teach it.” Following Shariah starts with learning it, and the duty passes from parents to children.', src: RN('use-of-shariah-in-everyday-life') },
    ]),
    ...sub(P2, 'the-personal-impact-of-sources-of-authority-9237', '3.2.2.8', [
      { n: 1, f: 'What is generosity in Islam, and what are the sources?', b: 'Giving freely, through Zakah and sadaqah. Qur’an 3:92: spend from what you love; 2:261: the grain that grows seven ears. Hadith: the upper hand is better, and charity does not reduce wealth.', src: RN('personal-impact-sources-of-authority') },
      { n: 2, f: 'Give examples of sacrifice in Islam', b: 'Ibraheem (AS) ready to sacrifice his son (Eid al-Adha), the Muhajirun leaving home and property, the Ansar preferring others (59:9), and daily acts such as Fajr, fasting and Zakah.', src: RN('personal-impact-sources-of-authority') },
      { n: 3, f: 'What is Ikhlas, and what is its opposite?', b: 'Sincerity: doing deeds purely for Allah (98:5; “actions are by intentions”). Its opposite is riya’, showing off, which makes a deed lose its reward.', src: RN('personal-impact-sources-of-authority') },
      { n: 4, f: 'What is taqwa, and what is the verse about it?', b: 'Piety or awareness of Allah, an inner guard that keeps a person behaving well when unseen. Qur’an 49:13: the most honoured in Allah’s sight is the most righteous.', src: RN('personal-impact-sources-of-authority') },
      { n: 5, f: 'What is the teaching about hiding the faults of others, and what is its limit?', b: 'Whoever hides a Muslim’s faults, Allah hides his faults in this world and the next (Muslim). Do not hide injustice: report crimes to those who can stop them.', src: RN('personal-impact-sources-of-authority') },
      { n: 6, f: 'What does Islam teach about physical health?', b: 'The body has rights (Salman’s advice to Abu Darda), the strong believer is better, cleanliness is half of faith, be moderate in eating (7:31), avoid harm such as alcohol, and seek treatment.', src: RN('personal-impact-sources-of-authority') },
      { n: 7, f: 'What does Islam teach about mental health?', b: 'Remembrance of Allah brings peace (13:28), hardship is followed by ease (94:5-6), Allah does not burden a soul beyond its capacity (2:286), and seeking help is not weakness of faith.', src: RN('personal-impact-sources-of-authority') },
      { n: 8, f: 'What does Sahih Muslim 2564c say, and how does it link the qualities?', b: 'Allah does not look at your faces and wealth but at your hearts and deeds. The heart means ikhlas and taqwa; the deeds mean generosity, sacrifice and honesty. Looks and money do not decide worth.', src: RN('personal-impact-sources-of-authority') },
    ]),
    ...sub(P2, 'the-social-impact-of-sources-of-authority-9237', '3.2.2.9', [
      { n: 1, f: 'What are the rights of neighbours in Islam?', b: 'Safety, privacy, consideration (noise, parking, rubbish), kindness (greetings, gifts, food), help in need, and polite handling of disputes. Non-Muslim neighbours are owed them too. Source: Qur’an 4:36.', src: RN('social-impact-sources-of-authority') },
      { n: 2, f: 'What does Sahih al-Bukhari 6016 teach?', b: '“By Allah, he does not believe!” whose neighbour does not feel safe from his evil. It shows that faith and behaviour are linked and that safety and trust are the test.', src: RN('social-impact-sources-of-authority') },
      { n: 3, f: 'What is Amanat, and what are the sources?', b: 'A trust: property, secrets, positions or duties in a person’s care. Qur’an 4:58: render trusts to those due; 23:8; 8:27: do not betray trusts. Betraying a trust is a sign of a hypocrite.', src: RN('social-impact-sources-of-authority') },
      { n: 4, f: 'What is backbiting (ghibah), and how does it differ from slander (buhtan)?', b: 'Backbiting is mentioning something true about a person in his absence that he would dislike. Slander is false. Qur’an 49:12 compares backbiting to eating the flesh of a dead brother.', src: RN('social-impact-sources-of-authority') },
      { n: 5, f: 'When is mentioning someone’s faults permitted, and what is the remedy for backbiting?', b: 'When seeking justice, warning of danger or asking for a ruling. The remedy is to stay silent, defend the absent, seek forgiveness and ask pardon.', src: RN('social-impact-sources-of-authority') },
      { n: 6, f: 'What is arrogance (kibr), and what is its opposite?', b: 'Thinking oneself better and rejecting truth or looking down on people. No one with an atom’s weight of arrogance enters Paradise (Muslim). The opposite is humility (tawadu’). Iblis (7:12) was the first arrogant.', src: RN('social-impact-sources-of-authority') },
      { n: 7, f: 'What is jealousy (hasad), and how does it differ from ghibtah?', b: 'Hasad is wishing that another lose a blessing (113:5; 4:32). Ghibtah is wanting a similar good without wishing loss to the other. Remedy: gratitude and praying for the other person.', src: RN('social-impact-sources-of-authority') },
      { n: 8, f: 'How does the image of one body link these teachings?', b: 'The Prophet said believers in their mutual kindness are like one body (Bukhari and Muslim). When one neighbour suffers from gossip, envy, pride or betrayal, the whole community is harmed.', src: RN('social-impact-sources-of-authority') },
    ]),
    ...sub(P2, 'the-legal-impact-of-sources-of-authority-9237', '3.2.2.10', [
      { n: 1, f: 'What is the difference between a qadi and a mufti?', b: 'A qadi is a judge whose ruling (hukm) is binding. A mufti gives a fatwa, an opinion that guides but does not bind. Judges must judge with justice (4:58).', src: RN('legal-impact-sources-of-authority') },
      { n: 2, f: 'What does Islam teach about testimony?', b: 'Give truthful evidence even against yourself (4:135). Do not conceal it (2:283); write down debts and call witnesses (2:282); false testimony is a major sin (25:72).', src: RN('legal-impact-sources-of-authority') },
      { n: 3, f: 'What is riba, and what do 2:275 and the Final Sermon say?', b: 'Riba is an increase fixed in advance on a loan in return for time. Qur’an 2:275: Allah has permitted trade and forbidden interest. The Final Sermon cancelled riba, beginning with that owed to Abbas.', src: RN('legal-impact-sources-of-authority') },
      { n: 4, f: 'Give reasons why interest is forbidden', b: 'It exploits borrowers, creates debt traps, makes money from money alone, moves wealth from poor to rich, and is commanded by Allah. Trade is allowed because profit is linked to goods, work and shared risk.', src: RN('legal-impact-sources-of-authority') },
      { n: 5, f: 'Name Islamic alternatives to interest', b: 'Mudarabah (one partner gives money, the other work; shared profit), musharakah (shared profit and loss), murabaha (bank buys and sells at agreed profit), ijarah (leasing) and qard hasan (interest-free loan).', src: RN('legal-impact-sources-of-authority') },
      { n: 6, f: 'What are the rules of an Islamic will (wasiyyah)?', b: 'Up to one-third of the estate may be left to people or causes who are not already heirs; no bequest to an heir with a fixed share. Order: funeral costs and debts, then the will, then fixed shares (faraid).', src: RN('legal-impact-sources-of-authority') },
      { n: 7, f: 'Worked example: estate of £144,000 after debts, one-third to charity, wife, son, daughter. Find each share', b: 'Charity £48,000. Remainder £96,000. Wife one-eighth: £12,000. Children share £84,000 with the son twice the daughter: son £56,000, daughter £28,000. Total £144,000.', src: RN('legal-impact-sources-of-authority') },
      { n: 8, f: 'List key characteristics of an Islamic state', b: 'Law based on the Qur’an and Sunnah, justice and equality before the law, consultation (shura, 42:38; 3:159), trustworthy leadership, protection of life, faith and minorities, social welfare, defence, and accountability of the ruler.', src: RN('legal-impact-sources-of-authority') },
    ]),
  ],
};
